const processedBundles = bundlesData.map((bundle, index) => ({
  ...bundle,
  name: bundle.cardTitle,
  order: index + 1,
  showInGrid: true,
  cardImage: bundle.cardImage || 'https://images.unsplash.com/photo-1560750588-73207b1ef5b8?w=400&h=300&fit=crop&q=80',
  cardPrice: bundle.priceNew + ' EGP',
  cardRibbon: bundle.catalogueBadge,
  modalTitle: bundle.cardTitle,
  servicesLabel: bundle.servicesLabel || 'Includes',
  priceUnit: 'EGP',
  whyBoxText: bundle.whyBoxText || `${bundle.cardTitle} combines premium treatments for optimal results.`,
  gallery: [],
  sliderBgImage: 'https://images.unsplash.com/photo-1560750588-73207b1ef5b8?w=1200&h=600&fit=crop&q=80',
  sliderBgColor: 'bg-espresso',
  sliderCtaText: 'Learn More →',
  sliderOrder: bundle.showInSlider ? (index + 1) : 999,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString()
}));

localStorage.setItem('bundles', JSON.stringify(processedBundles));

const categories = [...new Set(bundlesData.map(b => b.parentCategory))];
const parentBundles = categories.map((cat, index) => ({
  id: cat.toLowerCase().replace(/\s+/g, '-').replace(/&/g, 'and'),
  name: cat,
  description: `Premium ${cat.toLowerCase()} packages`,
  isActive: true,
  order: index + 1,
  icon: '✨'
}));

localStorage.setItem('parentBundles', JSON.stringify(parentBundles));

console.log('✅ Loaded ' + processedBundles.length + ' bundles & ' + parentBundles.length + ' categories');
